// QR version 3-L, generated independently with ReportLab for this test URL.
export const qrUrl = 'https://example.com/from-qr';
export const qrMatrix = [
  '11111110001000100111001111111', '10000010010001000011001000001',
  '10111010100100010001101011101', '10111010010011001011101011101',
  '10111010010011001111001011101', '10000010001110111111001000001',
  '11111110101010101010101111111', '00000000100100010110100000000',
  '11101111100010001110111000100', '00111101110111011000101001001',
  '11110011101110111000001110111', '11000101111011101110110010010',
  '11100011101100110101111001011', '10110100111100110110011001001',
  '00000011011001000010010111011', '10110100010100010111110101010',
  '01101110111010001101111001011', '01100100100111011110111001101',
  '10011111111110111110011010011', '01100000001011101100100111010',
  '10101110001100110011111110000', '00000000111100110001100010111',
  '11111110100001000101101011011', '10000010111100010000100011001',
  '10111010101010001000111110000', '10111010010111011100110010100',
  '10111010111110111010100111001', '10000010100011101111101000010',
  '11111110111100110011100110011',
];

export function qrPixels({ inverted = false, rotated = false } = {}) {
  const size = (qrMatrix.length + 8) * 6;
  const data = new Uint8ClampedArray(size * size * 4);
  for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
    const row = Math.floor(y / 6) - 4, col = Math.floor(x / 6) - 4;
    const dark = qrMatrix[row]?.[col] === '1';
    const color = dark !== inverted ? 0 : 255;
    const index = (rotated ? x * size + size - y - 1 : y * size + x) * 4;
    data.set([color, color, color, 255], index);
  }
  return { data, width: size, height: size };
}
